INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Bus in der Informatik?', 2, '[{"text": "System zur Datenübertragung zwischen Komponenten", "correct": true, "because": "Verbindet CPU, RAM etc."}, {"text": "Öffentliches Verkehrsmittel", "correct": false, "because": "Kein IT-Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Bus?', 3, '[{"text": "Daten zwischen Hardwarekomponenten austauschen", "correct": true, "because": "Kommunikation ermöglichen"}, {"text": "Kosten direkt senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Bussen gibt es in einem Computer?', 5, '[{"text": "Datenbus", "correct": true, "because": "Datenübertragung"}, {"text": "Adressbus", "correct": true, "because": "Speicheradressen"}, {"text": "Steuerbus", "correct": true, "because": "Steuerbefehle"}, {"text": "Designbus", "correct": false, "because": "Kein IT-Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Datenbus überträgt Daten zwischen CPU und RAM. b) Er ist nur für externe Geräte relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Intern, nicht extern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Bus?', 4, '[{"text": "Busbreite", "correct": false, "because": "Datenmenge pro Takt"}, {"text": "Taktfrequenz", "correct": false, "because": "Übertragungsgeschwindigkeit"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Adressbus Speicheradressen überträgt?', 2, '[{"text": "Ja", "correct": true, "because": "Adressierung"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bus überträgt Steuerbefehle?', 3, '[{"text": "Steuerbus", "correct": true, "because": "Kontrollsignale"}, {"text": "Datenbus", "correct": false, "because": "Daten"}, {"text": "Adressbus", "correct": false, "because": "Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Funktion eines Busses?', 5, '[{"text": "Datenübertragung", "correct": true, "because": "Hauptzweck"}, {"text": "Adressierung", "correct": true, "because": "Speicherzugriff"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Bus verbindet CPU und RAM. b) Er ist nur für externe Geräte nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Intern, nicht extern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Bus unwichtig?', 4, '[{"text": "Busbreite", "correct": false, "because": "Übertragungskapazität"}, {"text": "Taktfrequenz", "correct": false, "because": "Geschwindigkeit"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Bus die Datenmenge pro Takt beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Busbreite"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Bus?', 4, '[{"text": "Schnelle Kommunikation", "correct": true, "because": "Zwischen Komponenten"}, {"text": "Effiziente Datenübertragung", "correct": true, "because": "Direkte Verbindung"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Bus nur für interne Datenübertragung ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch extern, z.B. USB"}, {"text": "Ja", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Bus?', 3, '[{"text": "Übertragungsgeschwindigkeit", "correct": true, "because": "Leistung"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Datenbus überträgt Daten. b) Der Steuerbus überträgt Speicheradressen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Steuerbus für Befehle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Bus?', 5, '[{"text": "Begrenzte Bandbreite", "correct": true, "because": "Busbreite begrenzt"}, {"text": "Single-Point-of-Failure", "correct": true, "because": "Busausfall kritisch"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei einem Bus?', 3, '[{"text": "Konfiguration und Fehlerbehebung", "correct": true, "because": "Hardwaremanagement"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Bus extern sein?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. USB"}, {"text": "Nein", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bus ist ein Beispiel für einen externen Bus?', 4, '[{"text": "USB", "correct": true, "because": "Externer Datenbus"}, {"text": "PCI", "correct": false, "because": "Intern"}, {"text": "RAM-Bus", "correct": false, "because": "Intern"}]');
